public class Solution {
    public int countOccurrences(int[] arr, int target) {

        // Raj Thomas 17th Jun 2026 1:31PM IST 
        int left = BS(arr, target, true);
        int right = BS(arr, target, false);

        if(left == -1 && right == -1) return 0;
        return right - left + 1;
    }

    private int BS(int[] nums, int target, bool isLeft) {

        int len = nums.Length;
        int low = 0, high = len - 1;
        int idx = isLeft ? int.MaxValue : int.MinValue;

        while(low <= high) {

            int mid = low + (high - low) / 2;
            if(nums[mid] == target) {
                if(isLeft) {
                    idx = Math.Min(idx, mid);
                    high = mid - 1;
                }
                else {
                    idx = Math.Max(idx, mid);
                    low = mid + 1;

                }
            }
            else if(nums[mid] < target) {
                low = mid + 1;
            }
            else {
                high = mid - 1;
            }

        }

        if(idx == int.MinValue || idx == int.MaxValue) return -1;
        return idx;
    }
}
